import { atom, read, update } from 'claude-code'
import type { Register } from 'claude-code'

// True once the model has answered at least once since the session started or was cleared,
// so the band stays out of the way on an empty session.
const hasReplied = atom({ plugin: 'quick-replies', key: 'hasReplied' } as const, false)

export function parseReplies(raw: string): string[] {
  return raw
    .split('|')
    .map(reply => reply.trim())
    .filter(reply => reply.length > 0)
    .slice(0, 9)
}

export const register: Register = (on, options) => {
  const replies = parseReplies(String(options.replies ?? ''))

  on('turn.complete', async ($, e, next) => {
    if (e.agentId === undefined) {
      await update($, hasReplied, () => true)
    }

    return next(e)
  })

  on('session.end', async ($, e, next) => {
    await update($, hasReplied, () => false)

    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    // What other mods draw in the band stays, under the buttons.
    const below = await next(e)
    const isQuiet =
      e.props.hasSurvey ||
      e.props.isWorking ||
      e.props.view.agentId !== undefined ||
      replies.length === 0 ||
      !(await read($, hasReplied))

    if (isQuiet) {
      return below
    }

    const { Box, Button } = $.ui.resolve(e)

    return (
      <Box flexDirection="column">
        <Box flexDirection="row" flexWrap="wrap" columnGap={1}>
          {replies.map((reply, index) => (
            <Button
              key={`reply-${index}`}
              label={reply}
              variant={index === 0 ? 'primary' : undefined}
              onPress={() => void $.prompt.submit({ text: reply, asUser: true })}
            />
          ))}
        </Box>
        {below}
      </Box>
    )
  })
}

